package in.industrend.social;import java.net.URI;import java.net.http.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Component;@Component class ConfigClient{private final HttpClient http=HttpClient.newHttpClient();private final String base,token;ConfigClient(@Value("${services.config.url}")String base,@Value("${services.internal-token}")String token){this.base=base;this.token=token;}String required(String key){try{var r=HttpRequest.newBuilder(URI.create(base+"/internal/v1/config/"+key)).header("X-Service-Token",token).GET().build();var x=http.send(r,HttpResponse.BodyHandlers.ofString());if(x.statusCode()!=200||x.body().isBlank())throw new IllegalStateException("Configuration is missing: "+key);return x.body();}catch(InterruptedException e){Thread.currentThread().interrupt();throw new IllegalStateException("Configuration request interrupted",e);}catch(Exception e){throw new IllegalStateException("Configuration is missing: "+key,e);}}String get(String key,String fallback){try{return required(key);}catch(Exception e){return fallback;}}}
